CREATE TABLE "NfseCredentialRequest" ("id" TEXT NOT NULL,"taxpayerId" TEXT NOT NULL,"economicRegistrationId" TEXT NOT NULL,"serviceActivityId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'SOLICITADO',"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"analyzedAt" TIMESTAMP(3),"enabledAt" TIMESTAMP(3),"decisionReason" TEXT,"termsVersion" TEXT NOT NULL DEFAULT 'DEMO-1',"termsAcceptedAt" TIMESTAMP(3) NOT NULL,"createdByUsuarioId" TEXT NOT NULL,"analyzedByUsuarioId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseCredentialRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseCredentialEvent" ("id" TEXT NOT NULL,"credentialId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"description" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "NfseCredentialEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseInvoiceData" ("id" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"economicRegistrationId" TEXT NOT NULL,"serviceActivityId" TEXT NOT NULL,"parameterId" TEXT NOT NULL,"serviceDescription" TEXT NOT NULL,"serviceLocation" TEXT,"taxableBaseDecimal" DECIMAL(18,2) NOT NULL,"rate" DECIMAL(9,6) NOT NULL,"ownIssDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"retainedIssDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"retentionType" TEXT NOT NULL DEFAULT 'PROPRIO',"calculationSnapshot" JSONB NOT NULL,"source" TEXT NOT NULL DEFAULT 'WEB',"authenticityUrl" TEXT NOT NULL,"qrPayload" TEXT NOT NULL,"replacedInvoiceId" TEXT,"replacementInvoiceId" TEXT,"rpsItemId" TEXT,"occasionalRequestId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseInvoiceData_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseEvent" ("id" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"description" TEXT NOT NULL,"payload" JSONB,"actorUsuarioId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "NfseEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseCorrectionLetter" ("id" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"reason" TEXT NOT NULL,"changes" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'REGISTRADA',"createdByUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "NfseCorrectionLetter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseRpsBatch" ("id" TEXT NOT NULL,"batchNumber" TEXT NOT NULL,"providerTaxpayerId" TEXT NOT NULL,"source" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'RECEBIDO',"signaturePolicy" TEXT NOT NULL DEFAULT 'INTERNAL_ALLOWED',"signatureStatus" TEXT NOT NULL DEFAULT 'NAO_EXIGIDA',"documentId" TEXT,"payloadHash" TEXT NOT NULL,"protocol" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" TIMESTAMP(3),"createdByUsuarioId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseRpsBatch_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseRpsItem" ("id" TEXT NOT NULL,"batchId" TEXT NOT NULL,"rpsNumber" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'RECEBIDO',"payload" JSONB NOT NULL,"invoiceId" TEXT,"replacedRpsNumber" TEXT,"cancelledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseRpsItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseDmsDeclaration" ("id" TEXT NOT NULL,"protocol" TEXT NOT NULL,"taxpayerId" TEXT NOT NULL,"economicRegistrationId" TEXT,"competence" TEXT NOT NULL,"direction" TEXT NOT NULL,"channel" TEXT NOT NULL,"detailMode" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PROTOCOLADA',"noMovement" BOOLEAN NOT NULL DEFAULT false,"rectifiesDeclarationId" TEXT,"serviceValueDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"deductionValueDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"ownIssDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"retainedIssDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"payload" JSONB NOT NULL,"createdByUsuarioId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseDmsDeclaration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseOccasionalRequest" ("id" TEXT NOT NULL,"requestNumber" TEXT NOT NULL,"providerTaxpayerId" TEXT NOT NULL,"takerTaxpayerId" TEXT,"serviceActivityId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'SOLICITADA',"serviceDescription" TEXT NOT NULL,"serviceValueDecimal" DECIMAL(18,2) NOT NULL,"deductionValueDecimal" DECIMAL(18,2) NOT NULL DEFAULT 0,"taxAmountDecimal" DECIMAL(18,2) NOT NULL,"paymentRequired" BOOLEAN NOT NULL DEFAULT true,"assessmentId" TEXT,"guideId" TEXT,"invoiceId" TEXT,"decisionReason" TEXT,"approvedAt" TIMESTAMP(3),"releasedAt" TIMESTAMP(3),"createdByUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseOccasionalRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseDeductionCredit" ("id" TEXT NOT NULL,"taxpayerId" TEXT NOT NULL,"economicRegistrationId" TEXT,"creditType" TEXT NOT NULL,"originDocument" TEXT NOT NULL,"constructionReference" TEXT,"originalAmountDecimal" DECIMAL(18,2) NOT NULL,"availableAmountDecimal" DECIMAL(18,2) NOT NULL,"status" TEXT NOT NULL DEFAULT 'DISPONIVEL',"documentId" TEXT,"createdByUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NfseDeductionCredit_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NfseDeductionConsumption" ("id" TEXT NOT NULL,"creditId" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"amountDecimal" DECIMAL(18,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "NfseDeductionConsumption_pkey" PRIMARY KEY ("id"));
